  'products.anchor.vtx': 'View High-Power Analog VTX Lineup',
  'products.anchor.fc': 'Buy NDAA Compliant Flight Controllers',
  'products.anchor.gimbal': 'Browse AI Gimbal & Payload Solutions',
  'products.anchor.elrs': 'Shop ELRS Long-Range Control Systems',
  'products.anchor.camera': 'View Industrial Camera Modules',
