  'about.milestone.2023.title': 'Global Reach',
  'about.milestone.2023.desc': 'Markets spanning 30+ countries, becoming a leading UAV OEM/ODM supplier',
  'about.milestone.2025.title': 'Intelligent Upgrade',
  'about.milestone.2025.desc': 'Integrated AI vision modules and automated drone-in-a-box systems for BVLOS commercialization',
  'about.culture.title': 'Corporate Culture',
