  'fcEscDetail.faq.subtitle': 'Common technical questions about this product.',
  'fcEscDetail.faq.q1': 'Why choose an H7 flight controller for industrial UAVs?',
  'fcEscDetail.faq.a1': 'The H7 processor (480MHz) provides essential computational headroom for complex Kalman filtering, real-time obstacle avoidance, and high-frequency PID loops — ensuring superior flight stability under demanding conditions.',
  'fcEscDetail.faq.q2': 'How does triple-redundant IMU improve UAV safety?',
  'fcEscDetail.faq.a2': 'Three independent inertial sensors on separate buses allow the FC to detect anomalies instantly and switch to a healthy sensor within milliseconds, preventing catastrophic failures from vibration or sensor drift.',
  'fcEscDetail.faq.q3': 'What are the advantages of FOC ESCs for heavy-lift drones?',
  'fcEscDetail.faq.a3': 'FOC ESCs deliver higher efficiency, lower noise, smoother motor control, and real-time DroneCAN/UART telemetry. This translates to up to 10% longer flight time and industrial-grade reliability.',

  // Per-SKU SEO TDK
  'fcEscDetail.tdk.stack-mini-f7-55a.title': 'Mini F7 Flight Controller Stack | 55A 4-in-1 ESC | 20×20mm FPV Stack',
  'fcEscDetail.tdk.stack-mini-f7-55a.desc': 'Ultra-compact Mini F7 stack with 55A BLHeli_32 ESC. Designed for 2-4 inch cinewhoops and sub-250g long-range drones. Features STM32F722 MCU and ≤30ms latency.',
  'fcEscDetail.tdk.stack-mini-f7-55a.h1': 'Mini F7 + 55A Stack: Ultra-Compact 20×20mm FPV Power System',
  'fcEscDetail.tdk.stack-mini-f7-40a.title': 'CANI Stack-Mini F7-40A | 20×20mm Mini Flight Tower | F722 FC + 40A ESC',
  'fcEscDetail.tdk.stack-mini-f7-40a.desc': 'Explore the CANI Stack-Mini F7-40A. Integrates 216MHz F722 processor with 40A industrial ESC, 6S support and bidirectional DShot. Designed for compact industrial UAVs and high-performance FPV.',
  'fcEscDetail.tdk.stack-mini-f7-40a.h1': 'CANI Stack-Mini F7-40A | 20×20mm Mini Flight Tower (F7 FC + 40A ESC)',
  'fcEscDetail.tdk.stack-f405-55a.title': 'CANI Stack F405-55A | 55A 4-in-1 ESC Industrial Flight Tower | UAV Power Control',
  'fcEscDetail.tdk.stack-f405-55a.desc': 'Deep dive into CANI Stack F405-55A. STM32F405 core with 55A high-redundancy ESC, native 6S support for industrial FPV and compact inspection UAVs. Superior EMI protection and thermal management.',
  'fcEscDetail.tdk.stack-f405-55a.h1': 'CANI Stack F405-55A | 30.5mm Industrial Full-Feature Flight Tower',
  'fcEscDetail.tdk.stack-f405-60a.title': 'CANI Stack F405-60A | 60A Heavy-Duty Flight Tower | Industrial UAV Power Control',
  'fcEscDetail.tdk.stack-f405-60a.desc': 'CANI Stack F405-60A flight controller ESC stack. 60A continuous per channel with CNC thermal armor, 6S native support for heavy-lift industrial UAVs. Bidirectional DShot telemetry with RPM filtering.',
