  'platforms.crossLink.title': 'Looking for Core Components Instead?',
  'platforms.crossLink.desc': 'All CANI multirotor platforms are powered by our proprietary components — redundant IMU flight controllers, Ardupilot/PX4 compatible ESCs, and MAVLink-enabled modules. Visit the Component Center for OEM/ODM integration.',
