  'platforms.faq.title': 'Industrial Multirotor Platform FAQ',
  'platforms.faq.subtitle': 'Common questions about choosing the right industrial multirotor UAV platform for enterprise missions',
  'platforms.faq.q1': 'Are CANI multirotor platforms compatible with Ardupilot and PX4?',
  'platforms.faq.a1': 'Yes. All CANI industrial multirotor platforms support full MAVLink protocol and are compatible with both Ardupilot and PX4 flight stacks, enabling seamless integration with existing ground control stations like QGroundControl and Mission Planner.',
  'platforms.faq.q2': 'What payload capacity and flight time can the C30 Heavy Lift UAV Platform achieve?',
  'platforms.faq.a2': 'The C30 Heavy Lift UAV Platform supports payloads up to 100kg+ with flight times of 30-60 minutes depending on payload weight. It features redundant IMU flight controllers, Level 7 wind resistance, and IP55 protection for all-weather industrial operations.',
  'platforms.faq.q3': 'Do you offer OEM/ODM drone manufacturing for bulk purchase?',
  'platforms.faq.a3': 'Yes. As an OEM/ODM drone manufacturer, CANI provides customized industrial multirotor platforms for system integrators and bulk purchase clients. We offer tailored airframe configurations, custom payload integrations, and white-label branding for enterprise UAV solutions.',

  'platforms.cta.title': 'Find the Right Industrial Multirotor Platform',
