  'softwarePage.groundStation.faq.title': 'Technical FAQ',
  'softwarePage.groundStation.faq.q1': 'What UAV protocols does CANI GCS support?',
  'softwarePage.groundStation.faq.a1': 'CANI GCS fully supports MAVLink v2 and STANAG 4586 international standards, compatible with PX4, ArduPilot, and all MAVLink-compliant flight controllers, meeting NATO military-grade interoperability requirements.',
  'softwarePage.groundStation.faq.q2': 'What is the difference between AES-256 and post-quantum cryptography (PQC)?',
  'softwarePage.groundStation.faq.a2': 'AES-256-GCM is the current highest-level symmetric encryption standard, widely used in military communications. PQC is a next-generation encryption algorithm designed to resist future quantum computer attacks. CANI GCS integrates both to ensure data security now and in the future.',
  'softwarePage.groundStation.faq.q3': 'Can the system operate in completely offline environments?',
  'softwarePage.groundStation.faq.a3': 'Yes. CANI GCS supports pre-loaded offline 3D map data, enabling full route planning, mission orchestration, and flight control even in fully disconnected or signal-jammed environments, ensuring continuity for critical missions like power inspection and emergency response.',
  'softwarePage.groundStation.faq.q4': 'How many UAVs can CANI GCS control simultaneously?',
  'softwarePage.groundStation.faq.a4': 'CANI GCS supports multi-UAV formation missions with a single station monitoring and commanding multiple UAVs for BVLOS operations. Typical industrial scenarios support 5-20 UAV coordinated formations depending on data link bandwidth and mission complexity.',

  'softwarePage.groundStation.cta.title': 'Get Industrial-Grade GCS Solution',
  'softwarePage.groundStation.cta.subtitle': 'Contact us for a CANI GCS enterprise demo and learn how MAVLink v2 with military-grade encryption elevates your UAV operation security and efficiency.',

