  'softwarePage.swarm.f1.title': 'AI Swarm Autonomy',
  'softwarePage.swarm.f1.desc': 'sMatrix edge computing enables 50+ UAV fully autonomous formation, obstacle avoidance, and dynamic task allocation',
  'softwarePage.swarm.f2.title': 'Auto-Succession System',
  'softwarePage.swarm.f2.desc': 'Faulty or low-battery UAVs auto-exit; standby units seamlessly take over missions with zero downtime',
