  'customSoftware.data.log': 'Multi-Format Log Audit',
  'customSoftware.data.log.desc': 'Records complete flight trajectories and sensor data, supports KML/KMZ export for 3D playback and incident review.',
  'customSoftware.data.twin': 'Digital Twin Synchronization',
  'customSoftware.data.twin.desc': 'Generated orthomosaic imagery seamlessly integrates with ArcGIS, Autodesk and other GIS/BIM platforms for full asset lifecycle management.',
  'customSoftware.dev.title': 'Developer Support & OEM/ODM Deep Customization',
  'customSoftware.dev.insight': 'We provide open architecture for OEM/ODM partners, breaking software black-box limitations.',
  'customSoftware.dev.sdk': 'Full-Feature SDK Interface',
  'customSoftware.dev.sdk.desc': 'C/C++, Python libraries (LibUtils) supporting MAVLink and proprietary protocols for rapid industry application development.',
  'customSoftware.dev.cross': 'Cross-Platform Compatibility',
  'customSoftware.dev.cross.desc': 'Stable operation on Windows, Linux, Android, and various handheld GCS terminals.',
  'customSoftware.dev.ui': 'UI/UX Brand Customization',
  'customSoftware.dev.ui.desc': 'Deep customization of exclusive operating interfaces based on client brand visual systems to enhance market recognition.',
