  'customSoftware.faq.title': 'Frequently Asked Questions',
  'customSoftware.faq.q1': 'What are the core advantages of industrial GCS over consumer apps?',
  'customSoftware.faq.a1': 'Industrial GCS prioritizes "deterministic execution" and "security isolation." Compared to consumer apps, CANI systems support 128-bit encrypted links, multi-source telemetry fusion, and complex sensor in-situ calibration. It is not just a remote controller but a professional mission management platform with log auditing and emergency fault handling.',
  'customSoftware.faq.q2': 'Does CANI UAV software support Beyond Visual Line of Sight (BVLOS) operations?',
  'customSoftware.faq.a2': 'Yes. Our software complies with 2026 BVLOS regulations (Part 108/SORA framework), integrates Remote ID broadcasting and real-time airspace alerts, and supports global remote command and control via 4G/5G networks.',
  'customSoftware.cta.title': 'Start Your Software Custom Project',
  'customSoftware.cta.desc': 'Contact our senior engineering team for an exclusive technical proposal and OEM/ODM quotation',
