  'customPayload.seo.title': 'Industrial UAV Payload Custom_37W VTX & EO/IR Gimbal Systems_CANI Technology',
  'customPayload.seo.desc': 'CANI Technology provides leading industrial UAV payload customization. Core products: 37W high-power VTX (50km link), ≤0.1mrad EO/IR gimbal, LiDAR, gas detection & drop payloads. MAVLink & PSDK deep integration for power, security, surveying OEM/ODM.',
  'customPayload.seo.keywords': 'industrial UAV payload,LiDAR laser radar mount,37W VTX,UAV gimbal custom,EO/IR infrared camera,50km VTX link,CANI Technology',
