  'customPayload.types.optical': 'Multi-Sensor Gimbals',
  'customPayload.types.optical.desc': 'Proprietary G10D & FLYIR-TX130DA gimbals integrating visible, LWIR, and LRF. Tri-axis servo control with ≤0.1mrad stabilization eliminates long-zoom jitter. AI-powered automatic vehicle/personnel target recognition and real-time dynamic lock-on.',
  'customPayload.types.communication': 'Mapping & 3D Modeling Payloads',
  'customPayload.types.communication.desc': 'High-performance LiDAR integration for vegetation-penetrating true terrain data. PDK enables rapid multispectral/hyperspectral camera adaptation for precision agriculture NDVI analysis.',
  'customPayload.types.sensor': 'Industrial Inspection Payloads',
  'customPayload.types.sensor.desc': 'Gas sensing: high-sensitivity TDLAS methane detector or multi-gas sensors with real-time data backhaul. NDT: ultrasonic testing (UT) or wall thickness probes for high-altitude tank and pressure vessel inspection.',
  'customPayload.types.radar': 'Radar & SAR Payloads',
