  'customPayload.custom.title': 'Deep Custom R&D (OEM/ODM)',
  'customPayload.custom.insight': 'CANI Technology excels at solving the deep SWaP-C (Size, Weight, Power, Cost) balance challenges in industrial payload integration.',
