  'customPayload.faq.title': 'Payload Custom R&D Technical FAQ',
  'customPayload.faq.q1': 'Can CANI payload systems operate in extreme environments?',
  'customPayload.faq.a1': 'Yes. Our payloads feature IP67 protection (dust/waterproof), operating reliably in industrial-grade wide-temperature environments from -20°C to +55°C.',
  'customPayload.faq.q2': 'How does the 37W high-power VTX affect battery life?',
  'customPayload.faq.a2': 'The system is deeply optimized for power efficiency, minimizing redundant power consumption while maintaining a stable 50km link. Combined with lightweight gimbals, it preserves thrust redundancy and maximizes operational radius.',
  'customPayload.faq.q3': 'How do I start a payload OEM customization project?',
  'customPayload.faq.a3': 'Simply provide your sensor SWaP specifications and mission objectives (e.g., zoom ratio, detection accuracy). Our engineering team will leverage PDK to deliver full-process support from interface definition to flight calibration.',

