  // ===== About Page - Three Tech Pillars =====
  'about.pillars.title': 'Three Core R&D Pillars',
  'about.pillars.subtitle': 'From RF signals to video links to software ecosystems — CANI masters the full-stack underlying technology of industrial UAVs',

  'about.pillar.rf.title': 'RF Engineering',
  'about.pillar.rf.subtitle': 'The Foundation of Wireless Transmission',
  'about.pillar.rf.desc': 'We specialize in wireless transmission module design, continuously pushing the limits of signal stability in complex industrial environments. From analog VTX to digital video links, from ELRS to data link radios, our RF laboratory ensures every component meets the stringent anti-interference requirements of long-range UAV missions.',
  'about.pillar.rf.custom.title': 'Customization',
  'about.pillar.rf.custom.desc': 'Custom frequency bands and power levels for VTX, data link radios, and ELRS to meet regional regulations and mission requirements.',
  'about.pillar.rf.spec1.label': 'Frequency Range',
  'about.pillar.rf.spec1.value': '900MHz / 1.2GHz / 2.4GHz / 5.8GHz',
  'about.pillar.rf.spec2.label': 'Max Output Power',
  'about.pillar.rf.spec2.value': '10W (37dBm)',
  'about.pillar.rf.spec3.label': 'Anti-Interference',
  'about.pillar.rf.spec3.value': 'FHSS / COFDM / AES-256 Encryption',
  'about.pillar.rf.spec4.label': 'Transmission Range',
  'about.pillar.rf.spec4.value': 'Up to 50km (line of sight)',

  'about.pillar.video.title': 'Video Link',
  'about.pillar.video.subtitle': 'The Soul of Vision',
  'about.pillar.video.desc': 'CANI leads in ultra-low latency video link technology. Whether it\'s the high-fidelity clarity of HD digital systems or the zero-delay response of analog VTX (A1, A2, A3 series), our hardware is engineered for the demanding environments of industrial inspection and high-speed operations.',
  'about.pillar.video.custom.title': 'Customization',
  'about.pillar.video.custom.desc': 'Custom PCBA layout for compact airframes with integrated cooling solutions for sustained high-output operation.',
  'about.pillar.video.spec1.label': 'Digital Latency',
  'about.pillar.video.spec1.value': '≤30ms (1080p)',
  'about.pillar.video.spec2.label': 'Analog VTX Series',
  'about.pillar.video.spec2.value': 'A1 / A2 / A3 Full Power Coverage',
  'about.pillar.video.spec3.label': 'Thermal Design',
  'about.pillar.video.spec3.value': 'CNC Aluminum Integrated Heatsink',
  'about.pillar.video.spec4.label': 'Operating Temp',
  'about.pillar.video.spec4.value': '-20°C to +60°C',

  'about.pillar.software.title': 'Software & Protocols',
  'about.pillar.software.subtitle': 'The Brain & Connectivity',
  'about.pillar.software.desc': 'Beyond hardware, we develop the neural network of UAVs. Our software team excels in embedded firmware optimization, proprietary communication protocols, and swarm ground control systems. We transform complex hardware into intuitive, reliable tools for large-scale industrial deployment.',
  'about.pillar.software.custom.title': 'Customization',
  'about.pillar.software.custom.desc': 'API integration, custom GCS interfaces, and proprietary swarm algorithms for specialized mission profiles.',
  'about.pillar.software.spec1.label': 'FC Firmware',
  'about.pillar.software.spec1.value': 'Betaflight / PX4 / ArduPilot Deep Integration',
  'about.pillar.software.spec2.label': 'Comm Protocols',
  'about.pillar.software.spec2.value': 'MAVLink / Proprietary FHSS / MSP',
  'about.pillar.software.spec3.label': 'Swarm System',
  'about.pillar.software.spec3.value': '1000+ UAV GCS + Formation Algorithms',
  'about.pillar.software.spec4.label': 'AI Integration',
  'about.pillar.software.spec4.value': 'YOLOv8 Object Detection / 4TOPS Inference',

  // ===== About Page - SEO Bottom Content =====
  'about.seo.manufacturer.title': 'Industrial UAV Core Component Original Manufacturer',
  'about.seo.manufacturer.p1': 'CANI Technology is a leading Chinese original manufacturer (OEM) of industrial UAV core components. Since 2015, we have focused on independent R&D and mass production of RF modules, video transmission systems, and embedded flight control software. As an industry source supplier, we provide complete OEM/ODM solutions — from chip-level design to finished product delivery — to UAV integrators and airframe manufacturers in 30+ countries worldwide.',
  'about.seo.manufacturer.p2': 'Core products include 37W high-power COFDM digital video links (50km range), multi-band analog VTX series (A1/A2/A3), industrial-grade ELRS control links, EO/IR dual-sensor gimbal pods, STM32 flight controllers with 48kHz ESC modules, and 1000+ UAV swarm ground station software. All products undergo rigorous EMC compatibility testing and -20°C to +60°C wide-temperature reliability verification for power inspection, emergency response, surveying, and logistics applications.',
  'about.seo.manufacturer.p3': 'Unlike component distributors and OBM resellers, CANI operates a complete RF laboratory, SMT production line, and embedded software development team. We support full-cycle technical services from PCB schematic design, RF impedance matching, and firmware development to complete system integration testing. Our R&D capabilities span FHSS frequency hopping, AES-256 communication encryption, adaptive bitrate (ABR) video transmission, and MBD model-based development.',

