  'acc.canifmtdetail.k472': 'CANI-FC v2.0 High-Performance Flight Controller | FMT Open-Source Autopilot',
  'acc.canifmtdetail.k473': 'CANI-FC v2.0 open-source flight controller with GD32F470 240MHz MCU, MATLAB/Simulink MBD, HIL/SIL/MIL simulation, Ethernet + CAN bus. Built for UAV research and industrial applications.',
  'acc.canifmtdetail.k474': 'What firmware does CANI-FC v2.0 support?',
  'acc.canifmtdetail.k475': 'CANI-FC v2.0 runs the FMT open-source autopilot firmware, supporting MATLAB/Simulink Model-Based Design (MBD) with one-click code generation and deployment.',
  'acc.canifmtdetail.k476': 'What simulation modes are supported?',
  'acc.canifmtdetail.k477': 'Full simulation coverage: Model-in-the-Loop (MIL), Software-in-the-Loop (SIL), Hardware-in-the-Loop (HIL), and open-loop simulation for algorithm verification.',
  'acc.canifmtdetail.k478': 'What vehicle types are compatible?',
  'acc.canifmtdetail.k479': 'Supports multi-rotor, fixed-wing, and VTOL (upcoming). Suitable for indoor/outdoor position hold, altitude hold, stabilize flight, and waypoint missions.',
  'acc.canifmtdetail.k480': 'GD32F470 High-Performance MCU',
  'acc.canifmtdetail.k481': '240MHz ARM Cortex-M4 with FPU, 512KB SRAM, 1024KB Flash. Built for real-time flight control with floating-point computation.',
  'acc.canifmtdetail.k482': 'MATLAB/Simulink MBD',
  'acc.canifmtdetail.k483': 'Graphical programming with one-click auto code generation. Deploy algorithms directly from Simulink to the flight controller.',
  'acc.canifmtdetail.k484': 'Full Simulation Coverage',
  'acc.canifmtdetail.k485': 'MIL, SIL, HIL, and open-loop simulation. Verify flight algorithms before deployment with confidence.',
  'acc.canifmtdetail.k486': 'Multi-Vehicle Support',
  'acc.canifmtdetail.k487': 'Multi-rotor, fixed-wing, VTOL (upcoming). Indoor/outdoor position hold, altitude hold, stabilize, waypoint missions.',
  'acc.canifmtdetail.k488': 'Rich Connectivity',
  'acc.canifmtdetail.k489': 'Ethernet, CAN bus, 5×UART, 3×I2C, SPI, 10×PWM, USB Type-C. Industrial-grade data throughput.',
  'acc.canifmtdetail.k490': 'Ultra-Compact Design',
  'acc.canifmtdetail.k491': 'Only 70×36×18.5mm, 39.3g. Exceptional size-to-performance ratio, optimized for space-constrained applications.',
