  'acc.elrsdetail.k549': 'A 915MHz long-range UAV receiver based on ExpressLRS. True diversity dual-circuit design with microsecond signal switching for BVLOS operations.',
  'acc.elrsdetail.k550': 'Ultra-micro 0.6g ExpressLRS receiver for small UAVs and FPV quads. 915MHz Nano architecture with long-range control and low power management.',
  'acc.elrsdetail.k551': 'Ultra-low latency 2.4G ELRS receiver with 1000Hz refresh rate. Optional micro ceramic antenna, ultra-lightweight, designed for high-speed FPV racing and close-range precision swarm operations.',
  'acc.elrsdetail.k552': 'Industrial 2.4G ELRS receiver with integrated LNA and 100mW PA. Supports 1000Hz refresh rate, solving 2.4G long-range telemetry dropout issues for mid-range inspections and FPV cruising.',
  'acc.elrsdetail.k553': 'Moxon rectangular directional antenna designed for 915MHz long-range control. 5.5dBi gain with 180° beamwidth, extending ELRS control range by 50%+, essential for BVLOS operations.',
  'acc.elrsdetail.k554': 'T-type omnidirectional antenna optimized for 2.4GHz ISM band. VSWR < 1.5 ensures over 96% RF power transmission, providing stable vertical polarization for 1000Hz high-refresh control links.',
  'acc.elrsdetail.k555': 'T-type omnidirectional antenna optimized for 915MHz industrial band. VSWR < 1.2 with 360° toroidal pattern, ideal for multi-angle long-range inspection and complex flight routes.',
  'acc.fcescdetail.k556': 'CANI-Pixhawk4: Redefining Open-Source Architecture Reliability',
