  'swarmpage.w200.k667': 'Sub-millimeter precision indoor formation with motion capture',
  'swarmpage.w200.k668': 'CANI W400 GPS Flagship Swarm Kit',
  'swarmpage.w200.k669': 'Outdoor large-scale GPS swarm coordination with RTK',
  'swarmpage.w200.k670': 'Collaborative Pioneer: W200 Swarm UAV — Full-Stack Distributed Swarm Platform',
  'swarmpage.w200.k671': 'Explore W200 distributed swarm protocols, digital mesh networking, and multi-agent coordination algorithms',
  'swarmpage.w200.k672': 'Start Your Swarm Drone Research',
  'swarmpage.w200.k673': 'The CANI W200 kit provides a ready-to-fly UWB swarm formation solution with centimeter-level positioning accuracy, enabling research teams to rapidly validate multi-agent algorithms and swarm intelligence protocols.',
  'swarmpage.w300.k674': 'W300 Flagship Swarm Drone Platform | Dual-RTK Precision | CANI UAV',
  'swarmpage.w300.k675': 'W300 is our flagship swarm drone for massive coordination and formation flight. Features dual-antenna RTK for superior heading accuracy, extended flight endurance, robust mesh digital links, and MoCap compatibility for sub-mm precision research.',
  'swarmpage.w300.k676': 'W300 advanced swarm UAV,professional formation flight drone,dual-antenna RTK swarm,high-performance swarm intelligence,long-endurance formation UAV,enterprise-grade swarm hardware,MoCap swarm,OptiTrack drone',
  'swarmpage.w300.k677': 'W300 Flagship High-Precision Swarm Coordination System',
  'swarmpage.w300.k678': 'The W300 is CANI UAV\\\'s premium swarm drone platform, engineered for organizations that demand the highest levels of precision and reliability in massive formation flight. Featuring dual-antenna RTK for superior heading accuracy and immunity to magnetic interference, robust digital mesh communication for seamless low-latency coordination across hundreds of nodes, and extended flight endurance for complex, long-duration swarm missions.',
  'swarmpage.w300.k679': 'Capture Refresh Rate',
  'swarmpage.w300.k680': 'CANI W200 UWB Swarm Kit',
  'swarmpage.w300.k681': 'Centimeter-level UWB positioning for indoor/outdoor swarm research',
  'swarmpage.w300.k682': 'CANI W400 GPS Flagship Swarm Kit',
  'swarmpage.w300.k683': 'Flagship Swarm Intelligence: W300 — Enterprise-Grade Software-Hardware Integration Platform',
  'swarmpage.w300.k684': 'Explore W300 self-healing Mesh networking, dual-RTK heading alignment, and swarm intelligence algorithms',
  'swarmpage.w300.k685': 'Start Enterprise-Grade Swarm Research',
  'swarmpage.w300.k686': 'The CANI W300 delivers the highest precision swarm platform for research teams and enterprise operators. Dual-antenna RTK, extended endurance, and MoCap compatibility for mission-critical formation flight.',
  'swarmpage.w400.k687': 'W400 Heavy-Lift Swarm Drone Platform | High-Payload & Persistence | CANI UAV',
  'swarmpage.w400.k688': 'W400 is our heavy-duty swarm drone designed for high-payload missions and extended flight endurance. Features dual-RTK, IP-rated weather protection, robust mesh digital communication, and 100 TOPS AI edge computing for tactical swarm intelligence.',
  'swarmpage.w400.k689': 'W400 heavy-lift swarm,industrial heavy-duty swarm UAV,long-endurance swarm coordination,multi-sensor swarm carrier,all-weather swarm drone,tactical swarm intelligence,GPS swarm platform,hexacopter swarm',
  'swarmpage.w400.k690': 'W400 Heavy-Duty High-Payload Swarm System',
  'swarmpage.w400.k691': 'Back to Swarm Systems',
  'swarmpage.w400.k692': 'Heavy-Lift',
  'swarmpage.w400.k693': 'W400 Heavy-Lift Swarm Formation Platform',
  'swarmpage.w400.k694': 'The W400 is CANI UAV\\\'s most robust heavy-lift swarm platform, engineered for missions where payload capacity and flight persistence are non-negotiable. With dual-antenna RTK for centimeter-level precision, an IP-rated weather-resistant airframe, and integrated digital mesh communication, the W400 excels in the most demanding environments for mission-critical swarm intelligence and heavy-payload autonomous operations.',
  'swarmpage.w400.k695': 'Hexa Wheelbase',
