  'swarmPage.seo.title': 'Industrial Drone Swarm Platforms & Technology | CANI UAV',
  'swarmPage.seo.desc': 'CANI UAV provides professional drone swarm platforms (W200/W300/W400) for massive coordination missions. Featuring high-precision RTK, MAVLink support, and autonomous swarm intelligence.',
  'swarmPage.seo.keywords': 'drone swarm,UAV swarm intelligence,multi-UAV control,swarm coordination,RTK positioning,MAVLink mesh network,autonomous swarm navigation,swarm drone kit',
  'swarmPage.hero.title': 'Integrated Drone Swarm Solutions & Coordination Platforms',
  'swarmPage.hero.subtitle': 'Centimeter-level RTK positioning, MAVLink mesh networking, and one-to-many autonomous fleet control — powering the next generation of massive drone coordination for research, defense, and industrial operations.',
  'swarmPage.feat.title': 'Core Swarm Technologies',
  'swarmPage.f1.title': 'Multi-Constellation GNSS + RTK',
  'swarmPage.f1.desc': 'Centimeter-level positioning accuracy via quad-constellation GNSS with RTK correction, ensuring precise spatial synchronization across the entire swarm fleet.',
  'swarmPage.f2.title': 'MAVLink Mesh Network',
  'swarmPage.f2.desc': 'Robust digital mesh communication enabling low-latency broadcast, inter-drone data sharing, and decentralized swarm coordination without single points of failure.',
  'swarmPage.f3.title': 'Open-Source ROS/PX4 Architecture',
  'swarmPage.f3.desc': 'Full compatibility with PX4/Ardupilot ecosystems and ROS middleware, enabling rapid algorithm deployment, custom behavior scripting, and seamless integration with research workflows.',
